function sigmoid(x) {
  if (x >= 0) {
    const z = Math.exp(-x);
    return 1 / (1 + z);
  }
  const z = Math.exp(x);
  return z / (1 + z);
}

function buyerCode(data) {
  const raw = String(data?.procuringEntity?.identifier?.id || "");
  const m = raw.match(/(\d{8,10})/);
  return m ? m[1] : null;
}

function competitionProcedureCategory(data) {
  const text = [
    data?.procurementMethodType,
    data?.procurementMethodDetails,
    data?.procurementMethod,
    data?.title
  ].filter(Boolean).join(" ").toLowerCase();

  if (/pricequotation|запит ціни/.test(text)) return "rfq";
  if (/особливост/.test(text)) return "open_special";
  if (/belowthreshold|спрощен/.test(text)) return "simplified";
  if (/відкриті торги|abovethreshold/.test(text)) {
    const d = tenderAnnouncementDate(data);
    if (d && d >= new Date(Date.UTC(2022, 9, 19))) return "open_special";
    return "open";
  }
  return "other";
}

function buildCompetitionForecast(data, fuelType, expectedValueWithoutVat) {
  if (!(Number(expectedValueWithoutVat) >= 1000000)) return null;

  const buyer = buyerCode(data);
  const h = buyer && COMPETITION_BUYER_HISTORY[buyer]
    ? COMPETITION_BUYER_HISTORY[buyer]
    : [0, 2.0, 0.36, 2];

  const count = Number(h[0]) || 0;
  const meanParticipants = Number(h[1]) || 2.0;
  const singleRate = Number(h[2]);
  const lastParticipants = Number(h[3]) || 2;
  const proc = competitionProcedureCategory(data);
  const title = String(data?.title || "").toLowerCase();

  const x = [
    Math.log(Number(expectedValueWithoutVat)),
    Math.log1p(count),
    meanParticipants,
    Number.isFinite(singleRate) ? singleRate : 0.36,
    Math.min(lastParticipants, 6),
    fuelType === "gasoline" ? 1 : 0,
    fuelType === "diesel" ? 1 : 0,
    proc === "rfq" ? 1 : 0,
    proc === "open_special" ? 1 : 0,
    proc === "simplified" ? 1 : 0,
    proc === "open" ? 1 : 0,
    /талон|картк|смарт/.test(title) ? 1 : 0,
    /налив|оптов|резервуар|бензовоз/.test(title) ? 1 : 0
  ];

  let decision = COMPETITION_MODEL.intercept;
  for (let i = 0; i < x.length; i++) {
    const z = (x[i] - COMPETITION_MODEL.mean[i]) / COMPETITION_MODEL.scale[i];
    decision += COMPETITION_MODEL.coef[i] * z;
  }

  const calibrated = sigmoid(
    COMPETITION_MODEL.calibrationIntercept +
    COMPETITION_MODEL.calibrationCoef * decision
  );

  const pTwoPlus = Math.min(0.99, Math.max(0.01, calibrated));
  const pOne = 1 - pTwoPlus;

  let conclusion;
  if (pTwoPlus >= 0.55) conclusion = "Ймовірніше, що в тендері буде два або більше учасників.";
  else if (pTwoPlus <= 0.45) conclusion = "Ймовірніше, що в тендері буде один учасник.";
  else conclusion = "Прогноз невизначений: один учасник і конкуренція двох або більше учасників мають близькі шанси.";

  let historyNote;
  if (count >= 3) {
    historyNote = `В історії цього замовника враховано ${count} завершених паливних тендерів; середня кількість учасників — ${meanParticipants.toFixed(1)}.`;
  } else if (count > 0) {
    historyNote = `Історія цього замовника обмежена: у вибірці лише ${count} завершених паливних тендерів.`;
  } else {
    historyNote = "У навчальній вибірці немає достатньої історії цього замовника; прогноз більше спирається на тип процедури, вартість і вид пального.";
  }

  return {
    one_participant_pct: Number((pOne * 100).toFixed(1)),
    two_plus_participants_pct: Number((pTwoPlus * 100).toFixed(1)),
    conclusion,
    buyer_history_tenders: count,
    buyer_mean_participants: count ? Number(meanParticipants.toFixed(2)) : null,
    history_note: historyNote,
    model_note: "Статистичний прогноз формує рекомендований режим конкуренції. Перед розрахунком користувач має підтвердити або змінити цей режим."
  };
}

function cors(origin) {
  const allow = ALLOWED_ORIGINS.includes(origin) ? origin : "";
  return {
    ...(allow ? { "Access-Control-Allow-Origin": allow } : {}),
    "Access-Control-Allow-Methods": "POST,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Vary": "Origin"
  };
}

function json(body, status, origin) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json; charset=utf-8", ...cors(origin) }
  });
}

function normalizeTenderId(value) {
  const input = String(value || "").trim();
  const lotMatch = input.match(/(-L\d+)$/i);
  const lotSuffix = lotMatch ? lotMatch[1].toUpperCase() : null;
  const parentInput = input.replace(/-L\d+$/i, "");
  const m = parentInput.match(/^UA-(\d{4})-(\d{2})-(\d{2})-(\d{6})-([A-Za-z])$/i);
  if (!m) return null;
  const parent = `UA-${m[1]}-${m[2]}-${m[3]}-${m[4]}-${m[5].toLowerCase()}`;
  const entered = parent + (lotSuffix || "");
  return { entered, parent, lotSuffix };
}

function findInternalId(obj) {
  const preferred = [
    obj?.id,
    obj?.data?.id,
    obj?.tender?.id,
    obj?.data?.tender?.id,
    obj?.tenderId,
    obj?.data?.tenderId
  ];
  for (const v of preferred) {
    if (typeof v === "string" && /^[0-9a-f]{32}$/i.test(v)) return v;
  }

  const seen = new Set();
  function walk(x, depth = 0) {
    if (!x || depth > 5) return null;
    if (typeof x === "string" && /^[0-9a-f]{32}$/i.test(x)) return x;
    if (typeof x !== "object" || seen.has(x)) return null;
    seen.add(x);
    if (Array.isArray(x)) {
      for (const v of x) {
        const found = walk(v, depth + 1);
        if (found) return found;
      }
      return null;
    }
    for (const [k, v] of Object.entries(x)) {
      if (/^(id|tenderId|tender_id)$/i.test(k) && typeof v === "string" && /^[0-9a-f]{32}$/i.test(v)) {
        return v;
      }
    }
    for (const v of Object.values(x)) {
      const found = walk(v, depth + 1);
      if (found) return found;
    }
    return null;
  }
  return walk(obj);
}

async function resolveTenderInternalId(tenderId) {
  const url = `https://prozorro.gov.ua/api/tenders/${encodeURIComponent(tenderId)}/summary`;
  const res = await fetch(url, {
    headers: {
      "Accept": "application/json",
      "User-Agent": "EURO5-Asystent-Tendernoi-Propozytsii/1.4 (+https://www.goodspending.com)"
    },
    redirect: "follow"
  });

  if (!res.ok) {
    throw new Error(`Не вдалося знайти тендер за ID у Prozorro (HTTP ${res.status})`);
  }

  const rawText = await res.text();
  let summary;
  try {
    summary = JSON.parse(rawText);
  } catch {
    throw new Error("Prozorro повернув некоректну відповідь під час пошуку тендера.");
  }

  const internalId = findInternalId(summary);
  if (!internalId) {
    throw new Error("Prozorro знайшов тендер, але не повернув внутрішній ID для завантаження даних.");
  }

  return { internalId, summaryUrl: url };
}

async function fetchTenderData(tenderId) {
  const resolved = await resolveTenderInternalId(tenderId);
  const apiUrl = `https://public-api.prozorro.gov.ua/api/2.5/tenders/${resolved.internalId}`;

  const res = await fetch(apiUrl, {
    headers: {
      "Accept": "application/json",
      "User-Agent": "EURO5-Asystent-Tendernoi-Propozytsii/1.4 (+https://www.goodspending.com)"
    },
    redirect: "follow"
  });

  if (!res.ok) {
    throw new Error(`Тендер знайдено, але повні дані Prozorro не завантажилися (HTTP ${res.status})`);
  }

  const payload = await res.json();
  const data = payload?.data || payload;
  if (!data || typeof data !== "object") {
    throw new Error("Prozorro повернув порожні або некоректні дані тендера.");
  }

  return {
    data,
    internalId: resolved.internalId,
    apiUrl,
    publicUrl: `https://prozorro.gov.ua/uk/tender/${encodeURIComponent(tenderId)}`
  };
}

function collectCpvCodes(data) {
  const codes = new Set();
  const add = v => {
    const s = String(v || "").trim();
    if (/^\d{8}-\d$/.test(s)) codes.add(s);
  };

  add(data?.classification?.id);
  for (const c of data?.additionalClassifications || []) add(c?.id);

  for (const item of data?.items || []) {
    add(item?.classification?.id);
    for (const c of item?.additionalClassifications || []) add(c?.id);
  }

  for (const lot of data?.lots || []) {
    add(lot?.classification?.id);
  }

  return [...codes];
}

function getExpectedValue(data) {
  const amount = Number(data?.value?.amount);
  if (!Number.isFinite(amount) || amount <= 0) {
    return { amount: null, vatBasis: "не визначено", vatIncluded: null };
  }

  let vatIncluded = null;
  if (typeof data?.value?.valueAddedTaxIncluded === "boolean") {
    vatIncluded = data.value.valueAddedTaxIncluded;
  } else if (typeof data?.value?.vatIncluded === "boolean") {
    vatIncluded = data.value.vatIncluded;
  }

  return {
    amount,
    vatBasis: vatIncluded === true ? "з ПДВ" : vatIncluded === false ? "без ПДВ" : "не визначено",
    vatIncluded
  };
}

function classifyFuelItem(item) {
  const text = [
    item?.description,
    item?.classification?.description,
    item?.classification?.id
  ].filter(Boolean).join(" ").toLowerCase();

  const cpv = String(item?.classification?.id || "");
  if (/^09132/.test(cpv) || /бензин|gasoline|petrol|а-9[2458]/i.test(text)) return "gasoline";
  if (/^09134/.test(cpv) || /дизел|diesel|дп\b/i.test(text)) return "diesel";
  return null;
}

function isLitres(item) {
  const unit = item?.unit || {};
  const text = [unit?.code, unit?.name, unit?.name?.uk, unit?.name?.en].filter(Boolean).join(" ").toLowerCase();
  return /\bltr\b|\blitre\b|\bliter\b|літр|литр/.test(text);
}

function extractStructuredFuel(data) {
  let gasoline = 0;
  let diesel = 0;
  let gasolineFound = false;
  let dieselFound = false;

  for (const item of data?.items || []) {
    const fuel = classifyFuelItem(item);
    const q = Number(item?.quantity);
    if (!fuel || !Number.isFinite(q) || q < 0 || !isLitres(item)) continue;

    if (fuel === "gasoline") {
      gasoline += q;
      gasolineFound = true;
    } else if (fuel === "diesel") {
      diesel += q;
      dieselFound = true;
    }
  }

  const fuelType = gasolineFound && dieselFound ? "mixed"
    : gasolineFound ? "gasoline"
    : dieselFound ? "diesel"
    : null;

  return {
    fuelType,
    gasolineVolumeL: gasolineFound ? gasoline : null,
    dieselVolumeL: dieselFound ? diesel : null,
    totalVolumeL: (gasolineFound || dieselFound) ? gasoline + diesel : null
  };
}


function extractPaymentTerms(data) {
  const milestones = Array.isArray(data?.milestones) ? data.milestones : [];
  const financing = milestones.filter(m => m?.type === "financing");
  if (!financing.length) return { advancePaymentPct: null, paymentDays: null, paymentNote: null };

  let advancePaymentPct = 0;
  let advanceFound = false;
  const postDays = [];

  for (const m of financing) {
    const pct = Number(m?.percentage);
    const days = Number(m?.duration?.days);
    if (m?.code === "prepayment" && Number.isFinite(pct) && pct >= 0) {
      advancePaymentPct += pct;
      advanceFound = true;
    }
    if (m?.code === "postpayment" && Number.isFinite(days) && days >= 0) postDays.push(days);
  }

  const paymentDays = postDays.length ? Math.max(...postDays) : null;
  const parts = [];
  if (advanceFound) parts.push(`передоплата ${advancePaymentPct.toFixed(2).replace(/\\.00$/, "")}%`);
  if (paymentDays !== null) parts.push(`післяплата до ${paymentDays} днів`);

  return {
    advancePaymentPct: advanceFound ? Number(advancePaymentPct.toFixed(2)) : 0,
    paymentDays,
    paymentNote: parts.length ? parts.join(", ") : null
  };
}



function supplyFormatFromText(value) {
  const text = String(value || "").toLowerCase();
  const retail = /(талон|паливн\w*\s+карт|смарт[-\s]?карт|скретч[-\s]?карт|відпуск.{0,40}азс|заправк.{0,40}азс|мереж.{0,20}азс)/i.test(text);
  const bulk = /(налив|бензовоз|автоцистерн|резервуар|ємност|емкост|оптов\w*\s+постав|поставка.{0,35}(склад|резервуар|ємніст))/i.test(text);
  if (retail && bulk) return "split";
  if (retail) return "retail";
  if (bulk) return "bulk";
  return "unknown";
}

function normalizeSupplyFormat(value) {
  const v = String(value || "").toLowerCase();
  return ["bulk","retail","split","unknown"].includes(v) ? v : "unknown";
}

function detectSupplyFormat(data, parsed, fuelType) {
  const allText = [
    data?.title,
    data?.description,
    ...(data?.items || []).flatMap(item => [item?.description, item?.classification?.description]),
    ...(data?.documents || []).map(d => d?.title)
  ].filter(Boolean).join(" ");

  const deterministicGlobal = supplyFormatFromText(allText);
  let global = deterministicGlobal;
  let gas = "unknown";
  let diesel = "unknown";

  for (const item of data?.items || []) {
    const fuel = classifyFuelItem(item);
    if (!fuel) continue;
    const fmt = supplyFormatFromText([
      item?.description,
      item?.classification?.description,
      ...(item?.deliveryAddress ? Object.values(item.deliveryAddress) : [])
    ].filter(Boolean).join(" "));
    if (fmt === "unknown") continue;
    if (fuel === "gasoline") gas = gas === "unknown" ? fmt : gas === fmt ? gas : "split";
    if (fuel === "diesel") diesel = diesel === "unknown" ? fmt : diesel === fmt ? diesel : "split";
  }

  const aiGlobal = normalizeSupplyFormat(parsed?.supply_format);
  const aiGas = normalizeSupplyFormat(parsed?.gasoline_supply_format);
  const aiDiesel = normalizeSupplyFormat(parsed?.diesel_supply_format);

  if (gas === "unknown" && aiGas !== "unknown") gas = aiGas;
  if (diesel === "unknown" && aiDiesel !== "unknown") diesel = aiDiesel;
  if (global === "unknown" && aiGlobal !== "unknown") global = aiGlobal;

  if (fuelType === "gasoline") {
    if (gas === "unknown" && ["bulk","retail"].includes(global)) gas = global;
    if (global === "unknown" && ["bulk","retail"].includes(gas)) global = gas;
  } else if (fuelType === "diesel") {
    if (diesel === "unknown" && ["bulk","retail"].includes(global)) diesel = global;
    if (global === "unknown" && ["bulk","retail"].includes(diesel)) global = diesel;
  } else if (fuelType === "mixed") {
    if (gas === "unknown" && ["bulk","retail"].includes(global)) gas = global;
    if (diesel === "unknown" && ["bulk","retail"].includes(global)) diesel = global;
    if (["bulk","retail"].includes(gas) && ["bulk","retail"].includes(diesel)) {
      global = gas === diesel ? gas : "split";
    }
  }

  const source = deterministicGlobal !== "unknown" || gas !== "unknown" || diesel !== "unknown"
    ? "дані Prozorro / автоматичне визначення"
    : aiGlobal !== "unknown" || aiGas !== "unknown" || aiDiesel !== "unknown"
      ? "аналіз умов тендера"
      : "не визначено";

  return {
    supplyFormat: global,
    gasolineSupplyFormat: gas,
    dieselSupplyFormat: diesel,
    source
  };
}

function tenderAnnouncementDate(data) {
  const candidates = [
    data?.tenderPeriod?.startDate,
    data?.enquiryPeriod?.startDate,
    data?.date,
    data?.dateModified
  ];
  for (const value of candidates) {
    if (!value) continue;
    const d = new Date(value);
    if (!Number.isNaN(d.getTime())) return d;
  }
  return null;
}

function monthPath(date) {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${y}-${m}`;
}

function previousMonth(date) {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() - 1, 1));
}

function parseUaDate(value) {
  const m = String(value || "").match(/^(\d{2})\.(\d{2})\.(\d{2}|\d{4})$/);
  if (!m) return null;
  let year = Number(m[3]);
  if (year < 100) year += 2000;
  return new Date(Date.UTC(year, Number(m[2]) - 1, Number(m[1])));
}

function formatUaDate(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
  return `${String(date.getUTCDate()).padStart(2, "0")}.${String(date.getUTCMonth() + 1).padStart(2, "0")}.${date.getUTCFullYear()}`;
}

function stripHtml(value) {
  return String(value || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function parseMinfinRows(html) {
  const rows = [];
  const trMatches = String(html || "").match(/<tr\b[\s\S]*?<\/tr>/gi) || [];
  for (const tr of trMatches) {
    const text = stripHtml(tr);
    const dm = text.match(/(\d{2}\.\d{2}\.\d{4})/);
    if (!dm) continue;
    const tail = text.slice((dm.index || 0) + dm[0].length);
    const pm = tail.match(/(\d{1,3}[,.]\d{2})/);
    if (!pm) continue;
    const date = parseUaDate(dm[1]);
    const price = Number(pm[1].replace(',', '.'));
    if (date && Number.isFinite(price) && price > 0) rows.push({ date, price });
  }
  return rows;
}

async function fetchMinfinPrice(slug, targetDate) {
  if (!(targetDate instanceof Date) || Number.isNaN(targetDate.getTime())) return null;
  const months = [targetDate, previousMonth(targetDate)];
  const candidates = [];

  for (const d of months) {
    const url = `https://index.minfin.com.ua/ua/markets/fuel/${slug}/${monthPath(d)}/`;
    try {
      const res = await fetch(url, {
        headers: {
          "Accept": "text/html,application/xhtml+xml",
          "User-Agent": "Mozilla/5.0 (compatible; EURO5-Tender-Assistant/1.0; +https://www.goodspending.com)"
        },
        redirect: "follow"
      });
      if (!res.ok) continue;
      const html = await res.text();
      candidates.push(...parseMinfinRows(html));
    } catch (_) {}
  }

  const target = Date.UTC(targetDate.getUTCFullYear(), targetDate.getUTCMonth(), targetDate.getUTCDate());
  const eligible = candidates.filter(x => x.date.getTime() <= target).sort((a,b) => b.date.getTime() - a.date.getTime());
  if (!eligible.length) return null;
  const chosen = eligible[0];
  return {
    source: "Minfin / Консалтингова група А-95",
    date: formatUaDate(chosen.date),
    priceWithVat: chosen.price,
    priceWithoutVat: chosen.price / (1 + UKRAINE_STANDARD_VAT)
  };
}


function parseEnkorrCurrentPrices(html) {
  const pageText = stripHtml(html);
  const dateMatch = pageText.match(/Ціни\s+в\s+Україні\s*\((\d{2}\.\d{2}\.(?:\d{2}|\d{4}))\)/i);
  const date = dateMatch ? parseUaDate(dateMatch[1]) : null;
  let gasoline = null;
  let diesel = null;

  const rows = String(html || "").match(/<tr\b[\s\S]*?<\/tr>/gi) || [];
  for (const row of rows) {
    const text = stripHtml(row);
    const nums = [...text.matchAll(/(\d{1,3}(?:[.,]\d{1,4}))/g)].map(m => Number(m[1].replace(",", ".")));
    if (nums.length < 2) continue;
    if (/\bA-?95\b/i.test(text)) gasoline = { wholesale: nums[0], retail: nums[1] };
    if (/\bDiesel\b|дизел/i.test(text)) diesel = { wholesale: nums[0], retail: nums[1] };
  }

  // Fallback for compact/plain HTML variants.
  if (!gasoline) {
    const m = pageText.match(/A-?95\s+(\d{1,3}[.,]\d+)\s+(\d{1,3}[.,]\d+)/i);
    if (m) gasoline = { wholesale: Number(m[1].replace(",", ".")), retail: Number(m[2].replace(",", ".")) };
  }
  if (!diesel) {
    const m = pageText.match(/(?:Diesel|Дизель)\s+(\d{1,3}[.,]\d+)\s+(\d{1,3}[.,]\d+)/i);
    if (m) diesel = { wholesale: Number(m[1].replace(",", ".")), retail: Number(m[2].replace(",", ".")) };
  }

  return { date, gasoline, diesel };
}

async function fetchEnkorrCurrentPrices() {
  try {
    const res = await fetch("https://enkorr.ua/", {
      headers: {
        "Accept": "text/html,application/xhtml+xml",
        "Accept-Language": "uk-UA,uk;q=0.9,en;q=0.7",
        "User-Agent": "Mozilla/5.0 (compatible; EURO5-Tender-Assistant/1.0; +https://www.goodspending.com)"
      },
      redirect: "follow"
    });
    if (!res.ok) return null;
    const parsed = parseEnkorrCurrentPrices(await res.text());
    if (!parsed?.gasoline && !parsed?.diesel) return null;
    return { source: "Enkorr", ...parsed };
  } catch (_) {
    return null;
  }
}

function percentDifference(a, b) {
  if (!(a > 0) || !(b > 0)) return null;
  return Math.abs(a / b - 1) * 100;
}

function daysBetween(a, b) {
  if (!(a instanceof Date) || !(b instanceof Date) || Number.isNaN(a) || Number.isNaN(b)) return null;
  return Math.abs(a.getTime() - b.getTime()) / 86400000;
}

function chooseMarketPrice(format, retailPrice, wholesalePrice, wholesaleUsable) {
  if (format === "retail") return retailPrice;
  if (format === "bulk" && wholesaleUsable) return wholesalePrice;
  return null;
}

const EURO5_RETAIL_URL='https://euro5.ua/tsiny-na-palne/';
function parseEuro5Retail(html){
 const strip=s=>s.replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/\s+/g,' ').trim();
 const result={},labels={'95':'a95','95 EURO':'a95premium','92':'a92','ДП':'dt','ДП EURO':'dtPremium','ГАЗ':'lpg'};
 const chunks=String(html).split(/<div\b[^>]*class=["'][^"']*\bfuel__col\b[^"']*["'][^>]*>/i).slice(1);
 for(const block of chunks){
  const title=block.match(/<div\b[^>]*class=["'][^"']*\belementor-heading-title\b[^"']*["'][^>]*>([\s\S]*?)<\/div>/i);
  const price=block.match(/<span\b[^>]*class=["'][^"']*\belementor-heading-title\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
  if(!title||!price)continue;
  const key=labels[strip(title[1])],value=Number(strip(price[1]).replace(',','.'));
  if(key&&Number.isFinite(value)&&value>0){if(result[key]!==undefined&&result[key]!==value)throw Error('Неоднозначні ціни Євро5');result[key]=value}
 }
 if(!(result.a95>0)||!(result.dt>0))throw Error('Стела Євро5: не знайдено звичайні А-95 та ДП');
 return result;
}
function euro5ObservationDate(date=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}

const EURO5_ARCHIVE_URL='https://raw.githubusercontent.com/ukrsedo/euro5-tender-bid-assistant/main/data/euro5-retail-history.json';
async function loadEuro5RetailContext(includeCurrent){
 const today=euro5ObservationDate(),context={today,live:null,archive:[]};
 await Promise.all([
  (async()=>{if(!includeCurrent)return;try{const r=await fetch(EURO5_RETAIL_URL,{headers:{'User-Agent':'Mozilla/5.0 (compatible; EURO5-Tender-Assistant/1.0)'},signal:AbortSignal.timeout(15000)});if(r.ok)context.live=parseEuro5Retail(await r.text())}catch(_){}})(),
  (async()=>{try{const r=await fetch(EURO5_ARCHIVE_URL,{signal:AbortSignal.timeout(15000)});if(r.ok){const data=await r.json();if(data.schema_version===1&&Array.isArray(data.observations))context.archive=data.observations.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&x.source_url===EURO5_RETAIL_URL&&x.prices_uah_l_with_vat)}}catch(_){}})()
 ]);
 return context;
}
function euro5RetailRecord(slug,targetDate,context){
 const key=euro5ObservationDate(targetDate),entry=context.archive.find(x=>x.date===key);
 const live=key===context.today?context.live?.[slug]:null;
 const price=live??entry?.prices_uah_l_with_vat?.[slug];
 if(!(price>0)||!Number.isFinite(Number(price)))return null;
 return {source:live!==null&&live!==undefined?'Євро5 — поточна стела':'Євро5 — архів стели',date:key.split('-').reverse().join('.'),priceWithVat:Number(price),priceWithoutVat:Number(price)/(1+UKRAINE_STANDARD_VAT)};
}
async function fetchRetailPrice(slug,targetDate,context){
 const own=euro5RetailRecord(slug,targetDate,context);
 if(own)return own;
 // Current-date retail MUST be EURO5; do not silently substitute Minfin.
 if(euro5ObservationDate(targetDate)===context.today)return null;
 return fetchMinfinPrice(slug,targetDate);
}

/**
 * Optional market fields are absent when reference data is unavailable.
 * @returns {Promise<Record<string, unknown> & {available: boolean}>}
 */
async function buildMarketReference(data, parsed, scope, supplyInfo) {
  const tenderDate = tenderAnnouncementDate(data);
  if (!tenderDate) return {
    available: false,
    note: "Не вдалося визначити дату оголошення для порівняння бюджету з ринком."
  };

  const now = new Date();
  const daysOld = Math.max(0, (now.getTime() - tenderDate.getTime()) / 86400000);
  const recentTender = daysOld <= 30;
  const benchmarkDate = recentTender ? now : tenderDate;
  const trendDate = recentTender ? now : tenderDate;
  const pastDate = new Date(trendDate.getTime() - 30 * 86400000);

  const fuelType = parsed?.fuel_type;
  const gasVol = Number(parsed?.gasoline_volume_l);
  const dieselVol = Number(parsed?.diesel_volume_l);

  const needGas = fuelType === "gasoline" || fuelType === "mixed";
  const needDiesel = fuelType === "diesel" || fuelType === "mixed";

  const retailContext=await loadEuro5RetailContext(recentTender);
  const [retailGas, retailDiesel, trendGas, trendGasPast, trendDiesel, trendDieselPast, enkorr] = await Promise.all([
    needGas ? fetchRetailPrice("a95", benchmarkDate, retailContext) : null,
    needDiesel ? fetchRetailPrice("dt", benchmarkDate, retailContext) : null,
    needGas ? fetchMinfinPrice("a95", trendDate) : null,
    needGas ? fetchMinfinPrice("a95", pastDate) : null,
    needDiesel ? fetchMinfinPrice("dt", trendDate) : null,
    needDiesel ? fetchMinfinPrice("dt", pastDate) : null,
    fetchEnkorrCurrentPrices()
  ]);

  // Enkorr wholesale is current only. It is used only for tenders recent enough
  // to make a current wholesale benchmark meaningful. Historical bulk tenders
  // stay unscored until a reliable historical Enkorr series is available.
  let enkorrMinfinGas = null, enkorrMinfinDiesel = null;
  if (enkorr?.date) {
    [enkorrMinfinGas, enkorrMinfinDiesel] = await Promise.all([
      enkorr?.gasoline ? fetchMinfinPrice("a95", enkorr.date) : null,
      enkorr?.diesel ? fetchMinfinPrice("dt", enkorr.date) : null
    ]);
  }

  const crossGas = percentDifference(enkorr?.gasoline?.retail, enkorrMinfinGas?.priceWithVat);
  const crossDiesel = percentDifference(enkorr?.diesel?.retail, enkorrMinfinDiesel?.priceWithVat);
  const crossCheckLimitPct = 5;
  const gasWholesaleParsedOk = !!enkorr?.gasoline?.wholesale && (crossGas === null || crossGas <= crossCheckLimitPct);
  const dieselWholesaleParsedOk = !!enkorr?.diesel?.wholesale && (crossDiesel === null || crossDiesel <= crossCheckLimitPct);
  const wholesaleDateGap = enkorr?.date ? daysBetween(tenderDate, enkorr.date) : null;
  const wholesaleRecentEnough = recentTender && enkorr?.date && wholesaleDateGap !== null && wholesaleDateGap <= 30;

  const retailGasNoVat = retailGas?.priceWithoutVat ?? null;
  const retailDieselNoVat = retailDiesel?.priceWithoutVat ?? null;
  const wholesaleGasNoVat = gasWholesaleParsedOk ? enkorr.gasoline.wholesale / (1 + UKRAINE_STANDARD_VAT) : null;
  const wholesaleDieselNoVat = dieselWholesaleParsedOk ? enkorr.diesel.wholesale / (1 + UKRAINE_STANDARD_VAT) : null;
  const gasWholesaleUsable = !!wholesaleRecentEnough && !!wholesaleGasNoVat;
  const dieselWholesaleUsable = !!wholesaleRecentEnough && !!wholesaleDieselNoVat;

  const globalFormat = normalizeSupplyFormat(supplyInfo?.supplyFormat);
  const gasFormat = globalFormat === "split" ? normalizeSupplyFormat(supplyInfo?.gasolineSupplyFormat) : globalFormat;
  const dieselFormat = globalFormat === "split" ? normalizeSupplyFormat(supplyInfo?.dieselSupplyFormat) : globalFormat;

  const gasSelected = chooseMarketPrice(gasFormat, retailGasNoVat, wholesaleGasNoVat, gasWholesaleUsable);
  const dieselSelected = chooseMarketPrice(dieselFormat, retailDieselNoVat, wholesaleDieselNoVat, dieselWholesaleUsable);

  let marketValue = null;
  if (fuelType === "gasoline" && gasVol > 0 && gasSelected > 0) {
    marketValue = gasVol * gasSelected;
  } else if (fuelType === "diesel" && dieselVol > 0 && dieselSelected > 0) {
    marketValue = dieselVol * dieselSelected;
  } else if (fuelType === "mixed" && gasVol > 0 && dieselVol > 0 && gasSelected > 0 && dieselSelected > 0) {
    marketValue = gasVol * gasSelected + dieselVol * dieselSelected;
  }

  // Trend uses Minfin at both dates. EURO5 is only the retail price level.
  const trendGasNoVat=trendGas?.priceWithoutVat??null,trendDieselNoVat=trendDiesel?.priceWithoutVat??null;
  let currentTrendValue = null;
  let pastTrendValue = null;
  if (fuelType === "gasoline" && gasVol > 0 && trendGasNoVat > 0) {
    currentTrendValue = gasVol * trendGasNoVat;
    if (trendGasPast?.priceWithoutVat > 0) pastTrendValue = gasVol * trendGasPast.priceWithoutVat;
  } else if (fuelType === "diesel" && dieselVol > 0 && trendDieselNoVat > 0) {
    currentTrendValue = dieselVol * trendDieselNoVat;
    if (trendDieselPast?.priceWithoutVat > 0) pastTrendValue = dieselVol * trendDieselPast.priceWithoutVat;
  } else if (fuelType === "mixed" && gasVol > 0 && dieselVol > 0 && trendGasNoVat > 0 && trendDieselNoVat > 0) {
    currentTrendValue = gasVol * trendGasNoVat + dieselVol * trendDieselNoVat;
    if (trendGasPast?.priceWithoutVat > 0 && trendDieselPast?.priceWithoutVat > 0) {
      pastTrendValue = gasVol * trendGasPast.priceWithoutVat + dieselVol * trendDieselPast.priceWithoutVat;
    }
  }

  const fuelTrend30dPct = currentTrendValue > 0 && pastTrendValue > 0
    ? (currentTrendValue / pastTrendValue - 1) * 100
    : null;

  const crossNotes = [];
  if (enkorr?.gasoline && crossGas !== null) crossNotes.push(`А-95: роздріб Enkorr vs Minfin ${crossGas.toFixed(1)}%`);
  if (enkorr?.diesel && crossDiesel !== null) crossNotes.push(`ДП: роздріб Enkorr vs Minfin ${crossDiesel.toFixed(1)}%`);

  const benchmarkLabel = globalFormat === "bulk"
    ? "оптовий ринок Enkorr"
    : globalFormat === "retail"
      ? [retailGas?.source, retailDiesel?.source].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(" / ") || "роздріб Євро5 недоступний"
      : globalFormat === "split"
        ? "окремий ринковий орієнтир для кожної позиції"
        : "не визначено";

  const common = {
    available: marketValue > 0,
    benchmarkType: globalFormat,
    benchmarkLabel,
    benchmarkContext: recentTender ? "current" : "historical",
    tenderDate: formatUaDate(tenderDate),
    retailReferenceDate: retailGas?.date || retailDiesel?.date || null,
    retailSource: [retailGas?.source,retailDiesel?.source].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(' / ') || null,
    retailGasolineSource: retailGas?.source || null,
    retailDieselSource: retailDiesel?.source || null,
    fuelTrendNote: 'Тренд розраховано за роздрібними цінами Minfin / Консалтингової групи А-95 на обидві дати.',
    trendEndDate: trendGas?.date || trendDiesel?.date || null,

    wholesaleReferenceDate: enkorr?.date ? formatUaDate(enkorr.date) : null,
    retailGasolinePriceWithoutVat: retailGasNoVat,
    retailDieselPriceWithoutVat: retailDieselNoVat,
    wholesaleGasolinePriceWithoutVat: wholesaleGasNoVat,
    wholesaleDieselPriceWithoutVat: wholesaleDieselNoVat,
    wholesaleGasolineUsable: gasWholesaleUsable,
    wholesaleDieselUsable: dieselWholesaleUsable,
    wholesaleCrosscheckNote: crossNotes.join("; ") || null,
    fuelTrend30dPct,
    trendStartDate: trendGasPast?.date || trendDieselPast?.date || formatUaDate(pastDate)
  };

  if (!(marketValue > 0)) {
    let note;
    if (globalFormat === "unknown") {
      note = "Формат постачання не визначено. Оберіть «Налив» або «Талони / паливні картки», щоб розрахувати бюджет замовника до ринку.";
    } else if (!recentTender && (globalFormat === "bulk" || gasFormat === "bulk" || dieselFormat === "bulk")) {
      note = "Для історичного тендера з наливом немає надійної щоденної оптової ціни Enkorr на дату тендера. Цей фактор не використовується в рейтингу.";
    } else if ((gasFormat === "bulk" && !gasWholesaleUsable) || (dieselFormat === "bulk" && !dieselWholesaleUsable)) {
      note = "Оптову ціну Enkorr не вдалося надійно підтвердити. Порівняння бюджету з ринком не розраховано.";
    } else {
      note = "Ринковий орієнтир знайдено не для всіх потрібних позицій або немає підтвердженого обсягу.";
    }
    return { ...common, note };
  }

  const gap = (scope.normalizedWithoutVat / marketValue - 1) * 100;
  const abs = Math.abs(gap).toLocaleString("uk-UA", { maximumFractionDigits: 2 });
  const text = Math.abs(gap) < 0.05
    ? "Очікувана вартість практично відповідає ринковій вартості такого обсягу."
    : `Очікувана вартість на ${abs}% ${gap > 0 ? "вища" : "нижча"} за ринкову вартість такого обсягу.`;

  return {
    ...common,
    marketValueWithoutVat: marketValue,
    budgetVsMarketPct: gap,
    text,
    referenceDate: globalFormat === "bulk" ? common.wholesaleReferenceDate : common.retailReferenceDate,
    note: globalFormat === "bulk"
      ? "Для наливу використано поточний оптовий орієнтир Enkorr. Роздрібну колонку Enkorr звірено з Minfin як контроль правильності даних."
      : globalFormat === "retail"
        ? "Для талонів / паливних карток використано: "+common.retailSource+". Поточна дата — стела Євро5; попередні дати — архів Євро5, а за його відсутності Minfin."
        : "Для кожної позиції використано орієнтир відповідно до підтвердженого формату постачання."
  };
}

function nbuDateKey(date) {
  return `${date.getUTCFullYear()}${String(date.getUTCMonth()+1).padStart(2,"0")}${String(date.getUTCDate()).padStart(2,"0")}`;
}

async function fetchNbuUsdRate(targetDate) {
  if (!(targetDate instanceof Date) || Number.isNaN(targetDate.getTime())) return null;
  for (let back = 0; back <= 7; back++) {
    const d = new Date(targetDate.getTime() - back * 86400000);
    const url = `https://bank.gov.ua/NBUStatService/v1/statdirectory/exchange?valcode=USD&date=${nbuDateKey(d)}&json`;
    try {
      const res = await fetch(url, { headers: { "Accept": "application/json" } });
      if (!res.ok) continue;
      const payload = await res.json();
      const row = Array.isArray(payload) ? payload.find(x => x?.cc === "USD") || payload[0] : null;
      const rate = Number(row?.rate);
      if (Number.isFinite(rate) && rate > 0) return { rate, date: formatUaDate(d), source: "НБУ" };
    } catch (_) {}
  }
  return null;
}

async function fetchPriceRiskHistory(targetDate){
  try{
    const res=await fetch('https://raw.githubusercontent.com/ukrsedo/euro5-tender-bid-assistant/main/data/market-series.json',{signal:AbortSignal.timeout(15000)});
    if(!res.ok)return {ready:false,reason:'Не вдалося отримати історичний ряд цін.'};
    const data=await res.json(),asOf=euro5ObservationDate(targetDate);
    if(data.schema_version!==1||!Array.isArray(data.records))return {ready:false,reason:'Некоректний ряд цін.'};
    return {ready:true,as_of:asOf,updated_at:data.updated_at,sources:data.sources,records:data.records.filter(r=>r.date<=asOf)};
  }catch(_){return {ready:false,reason:'Історичний ряд цін тимчасово недоступний.'}}
}

async function buildFxTrend(data) {
  const date = tenderAnnouncementDate(data);
  if (!date) return { available: false, note: "Не вдалося визначити дату для валютного тренду." };
  const pastDate = new Date(date.getTime() - 30 * 86400000);
  const [current, past] = await Promise.all([fetchNbuUsdRate(date), fetchNbuUsdRate(pastDate)]);
  if (!current || !past) return { available: false, note: "Не вдалося завантажити курс USD/UAH для 30-денного порівняння." };
  const change30dPct = (current.rate / past.rate - 1) * 100;
  return {
    available: true,
    currentDate: current.date,
    pastDate: past.date,
    change30dPct,
    note: "Валютний фактор розраховано за офіційним курсом USD/UAH НБУ."
  };
}

function validateScope(data) {
  const cpvCodes = collectCpvCodes(data);
  const allowedFound = cpvCodes.filter(code => ALLOWED_CPV.has(code) || /^09132/.test(code) || /^09134/.test(code));
  const expected = getExpectedValue(data);

  if (!cpvCodes.length) {
    return {
      ok: false,
      reason: "CPV_NOT_FOUND",
      message: "У даних Prozorro не знайдено CPV. Не вдалося автоматично перевірити, чи підходить тендер для цієї моделі.",
      cpvCodes,
      expected
    };
  }

  if (!allowedFound.length) {
    return {
      ok: false,
      reason: "CPV_OUT_OF_SCOPE",
      message: `CPV ${cpvCodes.join(", ")} не належить до паливних кодів, для яких розрахована ця модель.`,
      cpvCodes,
      expected
    };
  }

  if (!expected.amount) {
    return {
      ok: false,
      reason: "VALUE_NOT_FOUND",
      message: "У даних Prozorro не знайдено очікувану вартість. Розрахунок неможливий.",
      cpvCodes,
      allowedFound,
      expected
    };
  }

  let normalizedWithoutVat;
  let normalizationNote;

  if (expected.vatIncluded === false) {
    normalizedWithoutVat = expected.amount;
    normalizationNote = "Prozorro вказує очікувану вартість без ПДВ; сума використовується без перерахунку.";
  } else if (expected.vatIncluded === true) {
    normalizedWithoutVat = expected.amount / (1 + UKRAINE_STANDARD_VAT);
    normalizationNote = "Prozorro вказує очікувану вартість з ПДВ; суму перераховано без ПДВ за ставкою 20%. Користувач має перевірити суму перед розрахунком.";
  } else {
    return {
      ok: false,
      reason: "VAT_BASIS_UNKNOWN",
      message: "Очікувану вартість знайдено, але Prozorro не повернув однозначну ознаку ПДВ. Для розрахунку потрібна сума без ПДВ.",
      cpvCodes,
      allowedFound,
      expected
    };
  }

  if (normalizedWithoutVat < 1000000) {
    return {
      ok: false,
      reason: "VALUE_OUT_OF_SCOPE",
      message: `Очікувана вартість для розрахунку становить ${Math.round(normalizedWithoutVat).toLocaleString("uk-UA")} грн без ПДВ, тобто менше 1 млн грн. Такий тендер не входить до сфери застосування моделі.`,
      cpvCodes,
      allowedFound,
      expected,
      normalizedWithoutVat,
      normalizationNote
    };
  }

  return {
    ok: true,
    reason: "ELIGIBLE",
    message: "CPV і очікувана вартість відповідають сфері застосування моделі.",
    cpvCodes,
    allowedFound,
    primaryCpv: allowedFound[0],
    expected,
    normalizedWithoutVat,
    normalizationNote
  };
}

function aiTenderPayload(data) {
  const reduced = {
    tenderID: data?.tenderID,
    title: data?.title,
    description: data?.description,
    status: data?.status,
    procurementMethodType: data?.procurementMethodType,
    value: data?.value,
    items: data?.items,
    lots: data?.lots,
    documents: (data?.documents || []).map(d => ({
      title: d?.title,
      documentType: d?.documentType,
      format: d?.format,
      url: d?.url,
      datePublished: d?.datePublished
    })),
    tenderPeriod: data?.tenderPeriod,
    enquiryPeriod: data?.enquiryPeriod,
    guarantee: data?.guarantee,
    criteria: data?.criteria,
    features: data?.features,
    awards: data?.awards,
    milestones: data?.milestones
  };

  let s = JSON.stringify(reduced);
  if (s.length > 70000) s = s.slice(0, 70000);
  return s;
}

