export default {
  async fetch(request, env, ctx) {
    const origin = request.headers.get("Origin") || "";

    if (request.method === "OPTIONS") {
      if (!ALLOWED_ORIGINS.includes(origin)) return new Response(null, { status: 403 });
      return new Response(null, { headers: cors(origin) });
    }

    const url = new URL(request.url);

    if (request.method === "GET" && url.pathname === "/health") {
      return json({
        ok: true,
        service: "ЄВРО5 · Асистент тендерної пропозиції",
        version: "2026.10.14-buyer-history"
      }, 200, origin);
    }

    if (request.method === "POST" && url.pathname === "/buyer-history") return buyerHistoryRoute(request,origin,ctx);

    if (request.method !== "POST" || url.pathname !== "/tender-check") {
      return json({ error: "Не знайдено" }, 404, origin);
    }

    if (!env.AI_API_URL || !env.AI_API_KEY || !env.AI_MODEL) {
      return json({ error: "Підключення ШІ не налаштовано" }, 503, origin);
    }

    const body = await request.json().catch(() => ({}));
    const normalized = normalizeTenderId(body.tenderId);
    if (!normalized) {
      return json({ error: "Введіть коректний ID тендера Prozorro, наприклад UA-2026-09-08-002654-a" }, 400, origin);
    }

    let source;
    try {
      source = await fetchTenderData(normalized.parent);
    } catch (e) {
      return json({
        error: "Не вдалося завантажити цей тендер з Prozorro",
        detail: e.message,
        tenderId: normalized.parent
      }, 502, origin);
    }

    const scope = validateScope(source.data);
    if (!scope.ok) {
      return json({
        error: "Тендер не підходить для розрахунку або його не вдалося автоматично перевірити",
        detail: scope.message,
        reason: scope.reason,
        tender_id: normalized.parent,
        source_url: source.publicUrl,
        api_url: source.apiUrl,
        cpv_codes_found: scope.cpvCodes || [],
        expected_value_raw_uah: scope.expected?.amount ?? null,
        vat_basis: scope.expected?.vatBasis ?? "не визначено",
        expected_value_uah_without_vat: scope.normalizedWithoutVat ?? null,
        normalization_note: scope.normalizationNote ?? null
      }, 422, origin);
    }

    const structuredFuel = extractStructuredFuel(source.data);
    const structuredPayment = extractPaymentTerms(source.data);

    const payload = {
      model: env.AI_MODEL,
      messages: [
        { role: "system", content: SYSTEM_PROMPT },
        {
          role: "user",
          content:
`ID тендера: ${normalized.parent}
Перевірений CPV: ${scope.primaryCpv}
Очікувана вартість з Prozorro: ${scope.expected.amount} грн (${scope.expected.vatBasis})
Очікувана вартість для розрахунку без ПДВ: ${scope.normalizedWithoutVat} грн

Структуровані дані Prozorro:
${aiTenderPayload(source.data)}`
        }
      ],
response_format: { type: "json_object" }
    };

    const aiRes = await fetch(env.AI_API_URL, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${env.AI_API_KEY}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(payload)
    });

    if (!aiRes.ok) {
      const detail = await aiRes.text();
      return json({ error: "Запит до ШІ завершився помилкою", detail: detail.slice(0, 1200) }, 502, origin);
    }

    const raw = await aiRes.json();
    const content = raw?.choices?.[0]?.message?.content;
    if (!content) return json({ error: "Не вдалося розпізнати формат відповіді ШІ" }, 502, origin);

    let parsed;
    try {
      parsed = typeof content === "string" ? JSON.parse(content) : content;
    } catch {
      return json({ error: "ШІ повернув некоректний JSON" }, 502, origin);
    }

    parsed.conditions = cleanAiList(parsed.conditions, "conditions");
    parsed.actions = cleanAiList(parsed.actions, "actions");

    // Structured Prozorro item quantities override AI where they are available.
    if (structuredFuel.fuelType) parsed.fuel_type = structuredFuel.fuelType;
    if (structuredFuel.gasolineVolumeL !== null) parsed.gasoline_volume_l = structuredFuel.gasolineVolumeL;
    if (structuredFuel.dieselVolumeL !== null) parsed.diesel_volume_l = structuredFuel.dieselVolumeL;
    if (structuredFuel.totalVolumeL !== null) parsed.total_volume_l = structuredFuel.totalVolumeL;
    if (structuredFuel.totalVolumeL !== null) parsed.volume_source = "структуровані дані Prozorro";
    if (structuredPayment.advancePaymentPct !== null) parsed.advance_payment_pct = structuredPayment.advancePaymentPct;
    if (structuredPayment.paymentDays !== null) parsed.payment_days = structuredPayment.paymentDays;
    parsed.payment_note = structuredPayment.paymentNote || null;

    const supplyInfo = detectSupplyFormat(source.data, parsed, parsed.fuel_type || structuredFuel.fuelType);
    parsed.supply_format = supplyInfo.supplyFormat;
    parsed.gasoline_supply_format = supplyInfo.gasolineSupplyFormat;
    parsed.diesel_supply_format = supplyInfo.dieselSupplyFormat;
    parsed.supply_format_source = supplyInfo.source;

    const competitionForecast = buildCompetitionForecast(
      source.data,
      parsed.fuel_type || structuredFuel.fuelType,
      scope.normalizedWithoutVat
    );

    const signalDate=tenderAnnouncementDate(source.data),recentSignal=signalDate&&(Date.now()-signalDate.getTime())/86400000<=30;
    const [market, fx, priceRiskHistory] = await Promise.all([
      buildMarketReference(source.data, parsed, scope, supplyInfo),
      buildFxTrend(source.data),
      fetchPriceRiskHistory(recentSignal?new Date():signalDate)
    ]);

    return json({
      ...parsed,
      buyer_code: buyerCode(source.data),
      buyer_name: source.data?.procuringEntity?.name || null,
      tender_id: normalized.parent,
      entered_id: normalized.entered,
      lot_suffix: normalized.lotSuffix,
      source_url: source.publicUrl,
      api_url: source.apiUrl,
      eligibility: "відповідає сфері",
      cpv_code: scope.primaryCpv,
      cpv_codes_found: scope.cpvCodes,
      expected_value_raw_uah: scope.expected.amount,
      vat_basis: scope.expected.vatBasis,
      vat_rate: scope.expected.vatBasis === "з ПДВ" ? UKRAINE_STANDARD_VAT : 0,
      expected_value_uah: Number(scope.normalizedWithoutVat.toFixed(2)),
      normalization_note: scope.normalizationNote,
      market_comparison_available: market.available,
      market_reference_date: market.referenceDate ?? null,
      market_benchmark_type: market.benchmarkType ?? null,
      market_benchmark_label: market.benchmarkLabel ?? null,
      market_benchmark_context: market.benchmarkContext ?? null,
      tender_announcement_date: market.tenderDate ?? null,
      market_retail_reference_date: market.retailReferenceDate ?? null,
      market_retail_source: market.retailSource ?? null,
      market_retail_gasoline_source: market.retailGasolineSource ?? null,
      market_retail_diesel_source: market.retailDieselSource ?? null,
      fuel_market_trend_note: market.fuelTrendNote ?? null,
      market_wholesale_reference_date: market.wholesaleReferenceDate ?? null,
      market_retail_gasoline_price_uah_l_without_vat: market.retailGasolinePriceWithoutVat ?? null,
      market_retail_diesel_price_uah_l_without_vat: market.retailDieselPriceWithoutVat ?? null,
      market_wholesale_gasoline_price_uah_l_without_vat: market.wholesaleGasolinePriceWithoutVat ?? null,
      market_wholesale_diesel_price_uah_l_without_vat: market.wholesaleDieselPriceWithoutVat ?? null,
      market_wholesale_gasoline_usable: market.wholesaleGasolineUsable ?? false,
      market_wholesale_diesel_usable: market.wholesaleDieselUsable ?? false,
      market_wholesale_crosscheck_note: market.wholesaleCrosscheckNote ?? null,
      market_gasoline_price_uah_l_without_vat: market.gasolinePriceWithoutVat ?? null,
      market_diesel_price_uah_l_without_vat: market.dieselPriceWithoutVat ?? null,
      market_value_uah_without_vat: market.marketValueWithoutVat ?? null,
      budget_vs_market_pct: market.budgetVsMarketPct ?? null,
      budget_vs_market_text: market.text ?? null,
      market_comparison_note: market.note ?? null,
      price_risk_history: priceRiskHistory,
      fuel_market_trend_30d_pct: market.fuelTrend30dPct ?? null,
      fuel_market_trend_start_date: market.trendStartDate ?? null,
      fuel_market_trend_end_date: market.trendEndDate ?? null,
      usd_uah_change_30d_pct: fx.change30dPct ?? null,
      usd_uah_current_date: fx.currentDate ?? null,
      usd_uah_start_date: fx.pastDate ?? null,
      currency_note: fx.note ?? null,
      competition_forecast: competitionForecast,
      advance_payment_pct: parsed.advance_payment_pct ?? 0,
      payment_days: parsed.payment_days ?? null,
      payment_note: parsed.payment_note ?? null,
      scope_note: "Відповідність сфери застосування перевірено за структурованими даними публічного API Prozorro.",
      source_scope: "Основні дані тендера завантажено з Prozorro. Вкладені файли поки що не аналізуються автоматично."
    }, 200, origin);
  }
};
